-- mistri store layout: jobs, sqlite, version 1. Generated by scripts/store-layouts.mjs; never edit by hand.
CREATE TABLE "__mistri_job_policy" (
  singleton INTEGER PRIMARY KEY CHECK (singleton=1),
  version INTEGER NOT NULL CHECK (version=1),
  policy_json TEXT COLLATE BINARY NOT NULL CHECK (typeof(policy_json)='text' AND instr(policy_json,char(0))=0 AND length(CAST(policy_json AS BLOB)) BETWEEN 1 AND 4096),
  last_clock INTEGER NOT NULL CHECK (typeof(last_clock)='integer' AND last_clock BETWEEN 0 AND 9007199254740991),
  next_seq INTEGER NOT NULL CHECK (typeof(next_seq)='integer' AND next_seq BETWEEN 0 AND 9007199254740991)
);
CREATE TABLE "__mistri_job_job" (
  id TEXT COLLATE BINARY NOT NULL CHECK (typeof(id)='text' AND instr(id,char(0))=0 AND length(CAST(id AS BLOB)) BETWEEN 1 AND 36) PRIMARY KEY,
  seq INTEGER NOT NULL CHECK (typeof(seq)='integer' AND seq BETWEEN 0 AND 9007199254740991) UNIQUE,
  job TEXT COLLATE BINARY NOT NULL CHECK (typeof(job)='text' AND instr(job,char(0))=0 AND length(CAST(job AS BLOB)) BETWEEN 1 AND 128),
  version INTEGER NOT NULL CHECK (typeof(version)='integer' AND version>=1),
  idempotency_key TEXT COLLATE BINARY NOT NULL CHECK (typeof(idempotency_key)='text' AND instr(idempotency_key,char(0))=0 AND length(CAST(idempotency_key AS BLOB)) BETWEEN 1 AND 128),
  fingerprint TEXT COLLATE BINARY NOT NULL CHECK (typeof(fingerprint)='text' AND instr(fingerprint,char(0))=0 AND length(CAST(fingerprint AS BLOB)) BETWEEN 1 AND 64),
  input_json TEXT COLLATE BINARY NOT NULL CHECK (typeof(input_json)='text' AND instr(input_json,char(0))=0 AND length(CAST(input_json AS BLOB)) BETWEEN 1 AND 65536),
  provenance_json TEXT COLLATE BINARY NOT NULL CHECK (typeof(provenance_json)='text' AND instr(provenance_json,char(0))=0 AND length(CAST(provenance_json AS BLOB)) BETWEEN 1 AND 1024),
  state TEXT NOT NULL CHECK (state IN ('scheduled','leased','retry','succeeded','failed','cancelled','unknown')),
  attempts INTEGER NOT NULL CHECK (typeof(attempts)='integer' AND attempts BETWEEN 0 AND 131),
  max_attempts INTEGER NOT NULL CHECK (typeof(max_attempts)='integer' AND max_attempts BETWEEN 1 AND 32),
  redrives INTEGER NOT NULL CHECK (typeof(redrives)='integer' AND redrives BETWEEN 0 AND 3),
  attempt_limit INTEGER NOT NULL CHECK (typeof(attempt_limit)='integer' AND attempt_limit BETWEEN 1 AND 131),
  run_at INTEGER NOT NULL CHECK (typeof(run_at)='integer' AND run_at BETWEEN 0 AND 9007199254740991),
  created_at INTEGER NOT NULL CHECK (typeof(created_at)='integer' AND created_at BETWEEN 0 AND 9007199254740991),
  updated_at INTEGER NOT NULL CHECK (typeof(updated_at)='integer' AND updated_at BETWEEN 0 AND 9007199254740991),
  fence TEXT,
  lease_until INTEGER,
  cancel_requested INTEGER NOT NULL CHECK (cancel_requested IN (0,1)),
  last_code TEXT CHECK (last_code IN ('succeeded','rejected','not_authorized','timeout','shutdown','lease_expired','cancelled','input_invalid','handler_error','redriven')),
  result_json TEXT CHECK (result_json IS NULL OR (typeof(result_json)='text' AND length(CAST(result_json AS BLOB)) BETWEEN 1 AND 65536)),
  UNIQUE (job,idempotency_key),
  CHECK (attempts<=attempt_limit),
  CHECK ((state IN ('leased','unknown') AND typeof(fence)='text' AND length(fence)=36 AND typeof(lease_until)='integer' AND lease_until>=0 AND attempts>0)
    OR (state NOT IN ('leased','unknown') AND fence IS NULL AND lease_until IS NULL)),
  CHECK ((state='scheduled' AND attempts=0 AND last_code IS NULL) OR state<>'scheduled'),
  CHECK (result_json IS NULL OR state='succeeded')
);
CREATE TABLE "__mistri_job_attempt" (
  job_id TEXT COLLATE BINARY NOT NULL CHECK (typeof(job_id)='text' AND instr(job_id,char(0))=0 AND length(CAST(job_id AS BLOB)) BETWEEN 1 AND 36) REFERENCES "__mistri_job_job" (id) ON DELETE RESTRICT,
  attempt INTEGER NOT NULL CHECK (typeof(attempt)='integer' AND attempt BETWEEN 1 AND 131),
  fence TEXT UNIQUE CHECK (fence IS NULL OR (typeof(fence)='text' AND length(fence)=36)),
  started_at INTEGER NOT NULL CHECK (typeof(started_at)='integer' AND started_at BETWEEN 0 AND 9007199254740991),
  deadline INTEGER CHECK (deadline IS NULL OR typeof(deadline)='integer'),
  outcome TEXT NOT NULL CHECK (outcome IN ('leased','succeeded','failed','retry','unknown','cancelled','redriven')),
  code TEXT CHECK (code IN ('succeeded','rejected','not_authorized','timeout','shutdown','lease_expired','cancelled','input_invalid','handler_error','redriven')),
  finished_at INTEGER,
  operator TEXT CHECK (operator IS NULL OR (typeof(operator)='text' AND instr(operator,char(0))=0 AND length(CAST(operator AS BLOB)) BETWEEN 1 AND 128)),
  PRIMARY KEY (job_id,attempt),
  CHECK ((outcome='redriven' AND fence IS NULL AND deadline IS NULL AND code IS 'redriven' AND typeof(finished_at)='integer'
      AND finished_at=started_at AND operator IS NOT NULL)
    OR (outcome<>'redriven' AND fence IS NOT NULL AND typeof(deadline)='integer' AND deadline>started_at AND operator IS NULL
      AND ((outcome='leased' AND code IS NULL AND finished_at IS NULL)
        OR (outcome<>'leased' AND code IS NOT NULL AND code<>'redriven' AND typeof(finished_at)='integer' AND finished_at>=started_at))))
);
CREATE INDEX "__mistri_job_due" ON "__mistri_job_job" (state,run_at,seq);
